import {
  Group,
  Mesh,
  Shape,
  ExtrudeGeometry,
  PlaneGeometry,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  PointLight,
  Texture,
  Color,
} from 'three/webgpu';
import {
  uv,
  color,
  mix,
  smoothstep,
  fract,
  sin,
  dot,
  vec2,
  vec3,
  texture,
  Fn,
  length as tslLength,
} from 'three/tsl';
import { gsap } from 'gsap';

// deterministic pseudo-grain hash
const hash21 = Fn(([p]) => {
  return fract(sin(dot(p, vec2(12.9898, 78.233))).mul(43758.5453123));
});

function roundedRectShape(w, h, r) {
  const shape = new Shape();
  const x = -w / 2;
  const y = -h / 2;
  shape.moveTo(x + r, y);
  shape.lineTo(x + w - r, y);
  shape.quadraticCurveTo(x + w, y, x + w, y + r);
  shape.lineTo(x + w, y + h - r);
  shape.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  shape.lineTo(x + r, y + h);
  shape.quadraticCurveTo(x, y + h, x, y + h - r);
  shape.lineTo(x, y + r);
  shape.quadraticCurveTo(x, y, x + r, y);
  return shape;
}

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'pricing-card-2';
  const inner = new Group();
  root.add(inner);

  // ---- card geometry (extruded, beveled, PBR) ----
  const cardW = 2.0;
  const cardH = 2.5;
  const cardDepth = 0.12;
  const shape = roundedRectShape(cardW, cardH, 0.12);
  const cardGeo = new ExtrudeGeometry(shape, {
    depth: cardDepth,
    bevelEnabled: true,
    bevelThickness: 0.025,
    bevelSize: 0.025,
    bevelSegments: 3,
    curveSegments: 12,
  });
  cardGeo.translate(0, 0, -cardDepth / 2);

  // placeholder texture swapped once loaded
  const placeholderTex = new Texture();
  const texNode = texture(placeholderTex, uv());

  const uvNode = uv();
  const gradientMix = smoothstep(0.0, 1.0, uvNode.y);
  const inkColor = color(palette.ink);
  const surfaceColor = color(palette.surface);
  const accentColor = color(palette.accent);

  const tint = mix(surfaceColor, inkColor, gradientMix);
  const tinted = mix(texNode.rgb, tint, 0.35);

  const grain = hash21(uvNode.mul(500.0)).sub(0.5).mul(0.05);
  const grained = tinted.add(vec3(grain, grain, grain));

  // thin accent stripe near top edge — the one accent element, kept small
  const stripeMask = smoothstep(0.9, 0.915, uvNode.y).mul(
    smoothstep(0.955, 0.94, uvNode.y)
  );
  const finalColor = mix(grained, accentColor, stripeMask.mul(0.85));

  const cardMat = new MeshPhysicalNodeMaterial();
  cardMat.colorNode = finalColor;
  cardMat.emissiveNode = vec3(accentColor).mul(stripeMask.mul(0.35));
  cardMat.roughness = 0.55;
  cardMat.metalness = 0.5;
  cardMat.clearcoat = 0.2;
  cardMat.clearcoatRoughness = 0.4;
  cardMat.anisotropy = 0.4;
  cardMat.anisotropyRotation = Math.PI / 2;

  const cardMesh = new Mesh(cardGeo, cardMat);
  inner.add(cardMesh);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    if (THREE.SRGBColorSpace) tex.colorSpace = THREE.SRGBColorSpace;
    texNode.value = tex;
    cardMat.needsUpdate = true;
  });

  // ---- contact shadow (grounded object) ----
  const shadowGeo = new PlaneGeometry(cardW * 1.4, cardH * 0.35, 1, 1);
  const shUv = uv();
  const centered = shUv.sub(vec2(0.5, 0.5));
  const dist = tslLength(centered.mul(vec2(1.0, 2.2)));
  const shadowFalloff = smoothstep(0.5, 0.0, dist);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.colorNode = color(palette.surface);
  shadowMat.opacityNode = shadowFalloff.mul(0.5);
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -cardH / 2 - 0.18, -0.06);
  inner.add(shadowMesh);

  // ---- rim light (accent hue, node-local, capped) ----
  const rimLight = new PointLight(new Color(palette.accent), 0.7, 6, 2.0);
  rimLight.position.set(-1.3, 0.6, -0.8);
  inner.add(rimLight);

  // ---- optional cinematic primitives (spec says none, but honor config) ----
  const primitiveHandles = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const applyFn = ctx.primitives?.[prim.name];
    if (typeof applyFn === 'function') {
      const handle = applyFn(inner, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- weighted-settle entrance (static composition afterwards) ----
  inner.scale.setScalar(0.98);
  inner.position.y = 0.12;
  const tl = gsap.timeline();
  tl.to(inner.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  });
  tl.to(
    inner.position,
    {
      y: 0,
      duration: 0.9,
      ease: 'power4.out',
    },
    0
  );

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    for (const h of primitiveHandles) {
      h.cleanup?.();
    }
    cardGeo.dispose();
    cardMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    placeholderTex.dispose();
    if (texNode.value && texNode.value !== placeholderTex) {
      texNode.value.dispose?.();
    }
    inner.remove(rimLight);
    root.clear();
  };

  return root;
}
